script:
// ph_projekte: Button „Projekt anlegen“ in PH Anfrage (PLAN.md WP2/WP4). Server: ph_projekte.api.projekt_aus_anfrage
frappe.ui.form.on("PH Anfrage", {
	refresh(frm) {
		if (frm.is_new()) return;
		if (frm.doc.folgedokument_doctype === "PH Projekt" && frm.doc.folgedokument) {
			frm.add_custom_button(__("Projekt öffnen"), () => frappe.set_route("Form", "PH Projekt", frm.doc.folgedokument), __("Aktionen"));
			return;
		}
		if (["Spam", "Verloren"].includes(frm.doc.status)) return;
		frm.add_custom_button(__("Projekt anlegen"), () => {
			const d = new frappe.ui.Dialog({
				title: __("Projekt aus Anfrage"),
				fields: [
					{ fieldname: "projektart", fieldtype: "Select", label: __("Projektart"), options: ["Wohnung", "Haus", "Kueche", "Bad", "Hotel", "Objekt", "Yacht", "Outdoor", "Sonstiges"], default: "Wohnung", reqd: 1 },
					{ fieldname: "titel", fieldtype: "Data", label: __("Projekttitel"), default: frm.doc.objektart || frm.doc.projektart || "" },
				],
				primary_action_label: __("Anlegen"),
				primary_action(values) {
					frappe.call({ method: "ph_projekte.api.projekt_aus_anfrage", args: { anfrage: frm.doc.name, ...values }, freeze: true, freeze_message: __("Projekt wird angelegt …") }).then((r) => {
						d.hide();
						if (r.message) frappe.set_route("Form", "PH Projekt", r.message);
					});
				},
			});
			d.show();
		}, __("Aktionen"));
	},
});
